const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define a geometry covering Beira and its neighborhood Manga in Mozambique.
    const geometry = ee.Geometry.Polygon([[
        [34.75, -19.90],
        [34.95, -19.90],
        [34.95, -19.75],
        [34.75, -19.75],
        [34.75, -19.90]
    ]]);

    // Define the specific dates of interest.
    const date1 = '2019-03-09';
    const date2 = '2019-03-24';

    // 2. Data Acquisition & Check
    // Use the VIIRS Day/Night Band daily composites.
    const collection = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1').select('avg_rad');

    // Get the image for the first date.
    const image1 = collection.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
    // Get the image for the second date.
    const image2 = collection.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

    // Check if both images exist.
    const image1Exists = ee.Number(ee.List([image1]).removeAll([null]).size());
    const image2Exists = ee.Number(ee.List([image2]).removeAll([null]).size());

    if (image1Exists.getInfo() === 0 || image2Exists.getInfo() === 0) {
        console.log(`Image found for ${date1}: ${image1Exists.getInfo() > 0}`);
        console.log(`Image found for ${date2}: ${image2Exists.getInfo() > 0}`);
        console.log("Evidence: At least one of the required daily images is missing from the collection.");
        console.log("C1");
        return;
    }

    // 3. Processing & Calculation
    // We only want to compare pixels that are lit in at least one image to avoid averaging over large dark areas.
    // Create a mask where radiance is greater than a small threshold (e.g., 0.5 nW cm-2 sr-1).
    const litAreaMask = image1.gt(0.5).or(image2.gt(0.5));
    const image1_masked = image1.updateMask(litAreaMask);
    const image2_masked = image2.updateMask(litAreaMask);

    const commonReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats1 = image1_masked.reduceRegion({
        reducer: commonReducer,
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    });

    const stats2 = image2_masked.reduceRegion({
        reducer: commonReducer,
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    });

    // Extract values. Use .get() which returns a server-side object.
    const mean1_server = stats1.get('avg_rad_mean');
    const count1_server = stats1.get('avg_rad_count');
    const mean2_server = stats2.get('avg_rad_mean');
    const count2_server = stats2.get('avg_rad_count');

    // Evaluate server-side objects.
    const mean1 = ee.Number(mean1_server).getInfo();
    const count1 = ee.Number(count1_server).getInfo();
    const mean2 = ee.Number(mean2_server).getInfo();
    const count2 = ee.Number(count2_server).getInfo();

    // 4. Validation & Final Answer
    if (count1 === 0 || count2 === 0) {
        console.log(`Valid pixels on ${date1}: ${count1}`);
        console.log(`Valid pixels on ${date2}: ${count2}`);
        console.log("Evidence: No valid (lit) pixels found in the area of interest after masking.");
        console.log("C2");
        return;
    }

    if (mean1 === null || mean2 === null) {
        console.log(`Mean Radiance on ${date1}: ${mean1}`);
        console.log(`Mean Radiance on ${date2}: ${mean2}`);
        console.log("Evidence: Calculation resulted in a null value.");
        console.log("C3");
        return;
    }

    console.log(`Mean Radiance (${date1}): ${mean1.toFixed(2)} nW cm-2 sr-1`);
    console.log(`Mean Radiance (${date2}): ${mean2.toFixed(2)} nW cm-2 sr-1`);
    console.log(`Valid Pixel Count: ${count1}`);
    console.log(`Evidence: Comparing the mean radiance values for the two dates.`);

    if (mean2 < mean1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
